function icon(name,size=''){return `<svg class="icon ${size}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.file}</svg>`;}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function norm(value){return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').toLowerCase().replace(/\s+/g,' ').trim();}
function slugDate(s){if(!s)return 'Tarih bilgisi yok';const d=new Date(s);return Number.isFinite(+d)?d.toLocaleDateString('tr-TR',{day:'2-digit',month:'long',year:'numeric'}):String(s);}
function shortDate(s){if(!s)return '—';const d=new Date(s);return Number.isFinite(+d)?d.toLocaleDateString('tr-TR'):String(s);}
function short(s,n=125){s=String(s||'');return s.length>n?s.slice(0,n-1)+'…':s;}
function displayTitle(rec){return rec.title||short(rec.plain?.split('\n').find(x=>x.trim())||rec.source||rec.path?.at(-1)||'Başlıksız kayıt',110);}
function pill(kind){return `<span class="kind-badge kind-${esc(kind||'OTHER')}">${esc(kind==='OTHER'?'DİĞER':kind)}</span>`;}
function versionLabel(meta){return slugDate(meta.published);}
function extractCode(text){const m=/^(?:(?:AMC|GM|CS)\d+\s*)?(?:[A-Z]{3}\.[A-Z]{3}\.[0-9]+[A-Za-z]?|Article\s+\d+[a-z]?)/i.exec(text||'');return m?m[0]:'';}
function htmlHighlighted(text,query){const q=norm(query).split(' ').filter(x=>x.length>1)[0];const safe=esc(text);if(!q)return safe;const toks=q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');try{return safe.replace(new RegExp(`(${toks})`,'ig'),'<mark>$1</mark>');}catch{return safe;}}
function safeFilename(s){return String(s).replace(/[^A-Za-z0-9._-]+/g,'_').slice(0,100)||'easa-rules';}
function saveFile(name,data,type='text/plain;charset=utf-8'){const blob=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function bytesFromB64(str){const b=atob(str);const out=new Uint8Array(b.length);for(let i=0;i<b.length;i++)out[i]=b.charCodeAt(i);return out;}
function b64FromBytes(arr){const a=arr instanceof Uint8Array?arr:new Uint8Array(arr);let parts=[];for(let i=0;i<a.length;i+=32768)parts.push(String.fromCharCode(...a.subarray(i,i+32768)));return btoa(parts.join(''));}
async function compressJson(obj){let blob=new Blob([JSON.stringify(obj)],{type:'application/json'});if('CompressionStream' in window){const zipped=await new Response(blob.stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer();return {binary:new Uint8Array(zipped),compressed:true};}return {binary:new Uint8Array(await blob.arrayBuffer()),compressed:false};}
async function decompressJson(binary,compressed){let stream=new Blob([binary]).stream();if(compressed){if(!('DecompressionStream' in window))throw Error('Bu tarayıcı gzip açmayı desteklemiyor. Güncel Chrome veya Edge kullanın.');stream=stream.pipeThrough(new DecompressionStream('gzip'));}return JSON.parse(await new Response(stream).text());}
const DBNAME='easa_erules_cloud_cache_v3';let db=null;const ephemeral={releases:new Map(),annotations:new Map(),settings:new Map()};let persistent=false;const EasaCloud=window.EasaCloud;let cloudConnected=false;let cloudStarting=false;let syncPromise=null;
async function startDB(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open(DBNAME,1);r.onupgradeneeded=()=>{for(const name of ['releases','annotations','settings'])if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name,{keyPath:name==='releases'?'versionId':name==='annotations'?'id':'key'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Veritabanı başka sekmede açık olabilir.'));});persistent=true;}catch(err){db=null;persistent=false;console.warn('IndexedDB not available',err);}}
async function storeGet(name,key){if(!db)return ephemeral[name].get(key);return new Promise((resolve,reject)=>{const r=db.transaction(name,'readonly').objectStore(name).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function storeAll(name){if(!db)return [...ephemeral[name].values()];return new Promise((resolve,reject)=>{const r=db.transaction(name,'readonly').objectStore(name).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function storePut(name,value){if(!db){ephemeral[name].set(value[name==='releases'?'versionId':name==='annotations'?'id':'key'],value);return;}return new Promise((resolve,reject)=>{const tx=db.transaction(name,'readwrite');tx.objectStore(name).put(value);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
async function storeDel(name,key){if(!db){ephemeral[name].delete(key);return;}return new Promise((resolve,reject)=>{const tx=db.transaction(name,'readwrite');tx.objectStore(name).delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
const state={view:'library',familyId:null,releaseId:null,readerQuery:'',readerCategory:'ALL',readerKind:'ALL',readerLimit:90,selectedKey:null,globalQuery:'',globalKind:'ALL',globalFamily:'ALL',globalLimit:70,diffFamily:null,diffOld:null,diffNew:null,diffFilter:'ALL',diffRows:[],diffSelected:0,busy:false};
let releaseRows=[];let familyRows=[];let annotations=new Map();let settings=new Map();const cache=new Map();let activeDoc=null;let modalLocked=false;let pendingSearch=null;
function buildFamilies(){const grouped=new Map();for(const r of releaseRows){if(!grouped.has(r.familyId))grouped.set(r.familyId,{id:r.familyId,title:r.title,releases:[]});grouped.get(r.familyId).releases.push(r);}familyRows=[...grouped.values()].map(f=>{f.releases.sort((a,b)=>String(b.published).localeCompare(String(a.published)));f.active=settings.get('active:'+f.id)||f.releases[0]?.versionId;if(!f.releases.some(r=>r.versionId===f.active))f.active=f.releases[0]?.versionId;f.current=f.releases.find(r=>r.versionId===f.active);return f;}).sort((a,b)=>a.title.localeCompare(b.title));}
function getFamily(id){return familyRows.find(f=>f.id===id);}
function getReleaseMeta(id){return releaseRows.find(r=>r.versionId===id);}
function activeMeta(familyId){return getFamily(familyId)?.current;}
function pinnedCount(){return [...annotations.values()].filter(a=>a.bookmarked).length;}
async function refreshMetadata(){if(!EasaCloud.user()){releaseRows=[];annotations=new Map();settings=new Map();buildFamilies();updateSidebar();return;}const [rels,anns,active]=await Promise.all([EasaCloud.listReleases(),EasaCloud.listAnnotations(),EasaCloud.listActive()]);releaseRows=rels;annotations=new Map(anns.map(a=>[a.id,a]));settings=new Map(Object.entries(active).map(([family,version])=>['active:'+family,version]));buildFamilies();updateSidebar();}
function rowForDoc(doc,binary,compressed,meta){return {versionId:doc.versionId,familyId:doc.familyId,title:doc.title,published:doc.published,guid:doc.guid,count:doc.records.length,binary,compressed,dataFileId:meta.dataFileId,ownerId:EasaCloud.user()?.uid};}
/* v3 starts with zero documents; no bundled XML and no default records. */
async function getDoc(releaseId){const owner=EasaCloud.user();if(!owner)throw Error('Önce Google hesabınızla giriş yapın.');const meta=getReleaseMeta(releaseId);if(!meta)throw Error('İstenen mevzuat sürümü bulut kataloğunda bulunamadı.');const key=owner.uid+'|'+releaseId;if(cache.has(key))return cache.get(key);let row=await storeGet('releases',key);if(!row||row.dataFileId!==meta.dataFileId){const binary=await EasaCloud.getFile(meta.dataFileId);if(meta.dataHash&&await EasaCloud.sha256(binary)!==meta.dataHash)throw Error('İndirilen mevzuat dosyasının bütünlük kontrolü başarısız oldu.');row={...meta,versionId:key,binary,compressed:!!meta.dataCompressed,dataFileId:meta.dataFileId,ownerId:owner.uid};try{await storePut('releases',row);}catch(e){console.warn('Önbellek yazılamadı, bulut verisi kullanılacak:',e);}}const doc=await decompressJson(row.binary,row.compressed);if(doc.versionId!==releaseId)throw Error('İndirilen içerik, katalogdaki sürüm kimliğiyle eşleşmiyor.');cache.set(key,doc);if(cache.size>5)cache.delete(cache.keys().next().value);return doc;}
async function setActive(familyId,versionId){if(!getFamily(familyId)?.releases.some(r=>r.versionId===versionId))throw Error('Sürüm bu yayına ait değil.');await EasaCloud.saveActive(familyId,versionId);settings.set('active:'+familyId,versionId);buildFamilies();if(state.familyId===familyId){state.releaseId=versionId;activeDoc=await getDoc(versionId);state.selectedKey=null;}updateSidebar();}
function annotId(familyId,record){return familyId+'::'+record.key;}
function getAnnotation(familyId,record){return annotations.get(annotId(familyId,record))||{};}
async function updateAnnotation(id,patch){const prior=annotations.get(id)||{id,note:'',bookmarked:false};const val={...prior,...patch,id,updatedAt:new Date().toISOString()};await EasaCloud.saveAnnotation(val);annotations.set(id,val);updateSidebar();}
function updateSidebar(){document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===state.view));const a=document.getElementById('bookmarksTotal');if(a)a.textContent=pinnedCount();const b=document.getElementById('catalogTotal');if(b)b.textContent=familyRows.length;const c=document.getElementById('storageMessage');const u=EasaCloud.user();if(c)c.innerHTML=`<span class="status-dot" style="background:${u?(EasaCloud.driveReady()?'#39c6aa':'#e9a14d'):EasaCloud.configured(readCloudConfig())?'#7ea6de':'#d45e63'}"></span>${u?(EasaCloud.driveReady()?'Firebase + Drive bağlı':'Firebase bağlı · Drive bekliyor'):EasaCloud.configured(readCloudConfig())?'Proje hazır · Giriş bekleniyor':'İlk bağlantı kurulumu gerekli'}`;const box=document.getElementById('cloudAccount');if(box)box.textContent=u?(u.email||'Google hesabı'):'Oturum açılmadı';const signIn=document.getElementById('authButton');if(signIn){signIn.textContent='Google ile giriş';signIn.hidden=!!u;}const driveButton=document.getElementById('driveButton');if(driveButton)driveButton.hidden=!u||EasaCloud.driveReady();const outButton=document.getElementById('logoutButton');if(outButton)outButton.hidden=!u;}
function breadcrumb(){const list={library:'Mevzuat kütüphanesi',reader:'Mevzuat okuyucu',search:'Tüm mevzuatta arama',bookmarks:'Yer imleri ve notlar',versions:'Sürüm yönetimi',compare:'Sürüm karşılaştırması',settings:'Hesap ve bağlantı'};const text=state.view==='reader'?getFamily(state.familyId)?.title: list[state.view];return `EASA eRules <span>/</span> <b>${esc(short(text||list.library,70))}</b>`;}
function uiPage(title,subtitle,eyebrow='MEVZUAT YÖNETİMİ',actions=''){return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 class="page-title">${title}</h1><p class="lead">${subtitle}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function btn(label,action,kind='',ico='',extra=''){return `<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;}
function nav(to){state.view=to;state.busy=false;document.getElementById('sidebar').classList.remove('open');updateSidebar();document.getElementById('breadcrumbs').innerHTML=breadcrumb();window.scrollTo(0,0);renderScreen().catch(showError);}
function showLoading(message){document.getElementById('screen').innerHTML=`<div class="loading"><div><div class="spinner"></div>${esc(message)}</div></div>`;}
function showToast(message,kind=''){const p=document.getElementById('toasts');const n=document.createElement('div');n.className='toast '+kind;n.innerHTML=icon(kind==='error'?'alert':'check')+'<span>'+esc(message)+'</span>';p.appendChild(n);setTimeout(()=>n.remove(),5100);}
function showError(e){console.error(e);if(e?.code==='EASA_DRIVE_SCOPE_MISSING'){
  modal(`<h2>${icon('alert')} Google Drive erişim izni eksik</h2><p>Google oturumu açılmış olabilir; ancak Drive klasörlerini yönetme yetkisi doğrulanamadı. XML dosyanızda bir sorun yok.</p><div class="info-strip">${icon('info')}<div><b>Google Cloud Console</b> → <b>Google Auth Platform</b> → <b>Data Access</b> → <b>Add or remove scopes</b><br><code>https://www.googleapis.com/auth/drive.file</code> iznini ekleyip kaydedin. Google izin ekranında Drive erişimine onay verin.</div></div><div class="modal-actions">${btn('Kapat','close-modal')} ${btn('Drive için yeniden izin ver','drive','primary','cloud')}</div>`);return;}
  if(e?.code==='EASA_DRIVE_SERVICE_DISABLED'){
    const number = /^\d+$/.test(String(e.projectNumber||'')) ? String(e.projectNumber) : '';
    const configuredProject = readCloudConfig()?.projectId || '-';
    const openApi = number ? `<p><a href="https://console.cloud.google.com/apis/api/drive.googleapis.com/overview?project=${number}" target="_blank" rel="noopener noreferrer">Google Drive API'yi bu projede kontrol et</a></p>` : '';
    modal(`<h2>${icon('alert')} Google Drive API / Cloud proje kontrol\u00fc</h2>
      <p>Google, <b>bu iste\u011fin kullan\u0131ld\u0131\u011f\u0131 projede</b> Drive API eri\u015fimini etkin g\u00f6rm\u00fcyor. API ba\u015fka bir Cloud projesinde etkinle\u015ftirilmi\u015f olabilir.</p>
      <div class="info-strip">${icon('info')}<div><b>Uygulamada ayarl\u0131 Firebase Project ID:</b> <code>${esc(configuredProject)}</code><br>
      <b>Google'in istekte g\u00f6rd\u00fc\u011f\u00fc Cloud proje numarasi:</b> <code>${esc(number || 'Yan\u0131tta bulunamad\u0131')}</code></div></div>
      ${openApi}
      <p><b>Kontrol:</b> Firebase Console &gt; Project settings &gt; General alanindaki Project number ile yukaridaki numarayi kar\u015f\u0131la\u015ft\u0131r\u0131n. Ardindan ayn\u0131 projede Google Drive API'nin etkin oldu\u011fundan emin olun.</p>
      <details><summary>Google API teknik yan\u0131t\u0131</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;max-height:150px;overflow:auto">${esc(e.googleMessage||e.message)}</pre></details>
      <div class="modal-actions">${btn('Kapat','close-modal','primary')}</div>`);
    return;
  }
  showToast(e?.message||String(e),'error');}

function modal(html,lock=false){modalLocked=lock;document.getElementById('modalBody').innerHTML=html;document.getElementById('modalLayer').hidden=false;}
function closeModal(){if(modalLocked)return;document.getElementById('modalLayer').hidden=true;document.getElementById('modalBody').innerHTML='';}
function initLibrary(){const total=familyRows.reduce((s,f)=>s+(f.current?.count||0),0),versions=releaseRows.length;const card=f=>{const title=f.title.replace(/^Easy Access Rules for\s*/i,'');return `<section class="pub-card"><div class="pub-card-top"><div class="pub-icon">${icon('file','lg')}</div><span class="chip teal">${f.releases.length} sürüm</span></div><h3>${esc(title)}</h3><p class="pub-subtitle">${esc(f.title)}</p><div class="pub-meta"><span class="chip">${icon('calendar','sm')}${esc(shortDate(f.current?.published))}</span><span class="chip">${(f.current?.count||0).toLocaleString('tr-TR')} kayıt</span></div><div class="pub-bottom"><span>${esc(shortDate(f.current?.published))} · bulutta kayıtlı</span><button type="button" class="btn primary small" data-open-family="${esc(f.id)}">Mevzuatı aç ${icon('chevron','sm')}</button></div></section>`;};
const u=EasaCloud.user(),configured=EasaCloud.configured(readCloudConfig());const cards=familyRows.map(card).join('');const emptyMessage=!configured?`<h3>İlk kurulum gerekli</h3><p>GitHub deposunun kök dizinine Firebase ayarlarını içeren config.js dosyasını koyun. Daha önce giriş yaptığınız bilgisayardan Hesap ve bağlantı bölümünde dosyayı oluşturabilirsiniz.</p>${btn('Kurulum adımlarını aç','go-settings','primary','settings')}`:!u?`<h3>Bulut kütüphanesine giriş yapın</h3><p>Google hesabınızı bağlayarak Firebase kataloğunu ve Drive dosyalarınızı görüntüleyin.</p>${btn('Google ile giriş','signin','primary','cloud')}`:!EasaCloud.driveReady()?`<h3>Google Drive'ı bağlayın</h3><p>Kütüphaneye yeni XML yüklemek için Drive erişim iznini yenileyin.</p>${btn('Drive bağla','drive','primary','cloud')}`:`<h3>İlk mevzuatınızı yükleyin</h3><p>Bir EASA eRules XML dosyası seçin. Hem orijinal dosya hem aranabilir sürümü Google Drive'a kaydedilecektir.</p>${btn('XML dosyası seç','upload','primary','upload')}`;document.getElementById('screen').innerHTML=uiPage('Dijital Mevzuat Kütüphanesi','Bütün mevzuat yayınlarını ve sürümlerini Google Drive + Firebase üzerinden yönetin.','BULUT TABANLI EASA KÜTÜPHANESİ',btn('Yeni XML yükle','upload','','upload')+btn('Bulutu yenile','sync-cloud','subtle','cloud')+btn('Tümünde ara','go-search','subtle','search'))+`<div class="stats-grid"><div class="stat"><div class="stat-label">Mevzuat yayını</div><div class="stat-val">${familyRows.length}</div><div class="stat-desc">Farklı yayın ailesi</div></div><div class="stat"><div class="stat-label">Kayıtlı hükümler</div><div class="stat-val">${total.toLocaleString('tr-TR')}</div><div class="stat-desc">Seçili sürümlerdeki kayıtlar</div></div><div class="stat"><div class="stat-label">Arşivlenen sürüm</div><div class="stat-val">${versions}</div><div class="stat-desc">Buluttaki sürümler</div></div><div class="stat"><div class="stat-label">Yer imlerim</div><div class="stat-val">${pinnedCount()}</div><div class="stat-desc">Firebase'de saklanır</div></div></div><div class="section-heading"><h2>Mevzuat yayınları</h2><span class="hint">${familyRows.length} yayın · ${versions} sürüm</span></div><div class="pub-grid">${cards}<div class="empty-card"><div class="pub-icon">${icon(u?'plus':'cloud','lg')}</div>${emptyMessage}</div></div><div class="info-strip">${icon('info')}<div>Bu sürümün HTML kodunda örnek mevzuat veya XML metni bulunmaz. Orijinal XML'ler Google Drive'da, işlenmiş veri dosyaları Drive'da, mevzuat kataloğu ile notlar Firestore'da saklanır. XML güncellemeleri otomatik olarak EASA'dan çekilmez.</div></div>`;}
async function openFamily(familyId,releaseId=null,recordKey=null){const f=getFamily(familyId);if(!f){showToast('Mevzuat yayını bulunamadı.','error');return;}state.familyId=familyId;state.releaseId=releaseId||f.active;state.view='reader';state.readerQuery='';state.readerCategory='ALL';state.readerKind='ALL';state.readerLimit=90;state.selectedKey=recordKey;nav('reader');}
function getCategories(doc){const m=new Map();for(const r of doc.records)m.set(r.category,(m.get(r.category)||0)+1);return [...m].sort((a,b)=>b[1]-a[1]);}
async function renderReader(){const f=getFamily(state.familyId);if(!f){nav('library');return;}showLoading('Mevzuat sürümü açılıyor…');const currentId=state.releaseId||f.active;try{activeDoc=await getDoc(currentId);}catch(e){document.getElementById('screen').innerHTML=uiPage('Mevzuat açılamadı',f.title,'BULUT DOSYA ERİŞİMİ',btn('Drive bağla','drive','primary','cloud')+btn('Kütüphaneye dön','go-library','','back'))+`<div class="panel"><h3>${icon('alert')} Dosya indirilemedi</h3><p>${esc(e.message)}</p><p class="muted">Bu sürümün orijinal XML'i ve işlenmiş dosyası Google Drive'da saklanır. Drive erişimini etkinleştirdikten sonra yeniden açabilirsiniz.</p></div>`;return;}if(state.view!=='reader'||state.releaseId!==currentId)return;const doc=activeDoc;const versions=f.releases.map(x=>`<option value="${esc(x.versionId)}" ${x.versionId===currentId?'selected':''}>${esc(shortDate(x.published))}${x.versionId===f.active?' · aktif':''}</option>`).join('');const categories=getCategories(doc).map(([v,n])=>`<option value="${esc(v)}">${esc(v)} (${n})</option>`).join('');
const title=doc.title.replace(/^Easy Access Rules for\s*/i,'');document.getElementById('screen').innerHTML=`<div class="reader-container"><div class="reader-toolbar"><div class="reader-toolbar-left"><button class="btn icon-only" data-action="go-library" aria-label="Kütüphaneye dön">${icon('back')}</button><div class="ellipsis"><div class="reader-toolbar-title">${esc(title)}</div><div class="reader-toolbar-sub">${doc.records.length.toLocaleString('tr-TR')} kayıt · ${esc(slugDate(doc.published))} EASA XML yayını</div></div></div><div class="page-actions"><label class="sr-only" for="readerVersion">Mevzuat sürümü</label><select class="form-field" id="readerVersion" style="width:174px;min-width:0">${versions}</select>${btn('Sürümleri yönet','go-versions','small','history')}</div></div><div class="reader-main"><section class="browser-panel"><div class="browser-tools"><div class="browser-heading"><span>Mevzuat gezgini</span>${icon('filter','sm')}</div><div class="form-search">${icon('search')}<input class="form-field" id="readerQuery" placeholder="Madde kodu, başlık veya içerik…" autocomplete="off" aria-label="Bu mevzuatta ara" /></div><div class="select-wrap"><label class="sr-only" for="readerCategory">Bölüm filtresi</label><select class="form-field" id="readerCategory"><option value="ALL">Tüm mevzuat bölümleri</option>${categories}</select></div><div class="filter-chips" id="readerKinds"></div></div><div class="browser-result"><span id="readerCount"></span><span>Seçilen: ${esc(shortDate(doc.published))}</span></div><div class="rule-list" id="readerList"></div></section><article class="detail-panel" id="readerDetail" aria-live="polite"></article></div></div>`;
document.getElementById('readerCategory').value=state.readerCategory;document.getElementById('readerQuery').value=state.readerQuery;paintReaderChips();refreshReaderList();}
function paintReaderChips(){const el=document.getElementById('readerKinds');if(!el)return;el.innerHTML=['ALL','IR','DR','AMC','GM','CS','OTHER'].map(k=>`<button class="filter-chip ${state.readerKind===k?'active':''}" data-reader-kind="${k}">${k==='ALL'?'Tümü':k==='OTHER'?'Diğer':k}</button>`).join('');}
function readerMatches(record){if(state.readerCategory!=='ALL'&&record.category!==state.readerCategory)return false;if(state.readerKind!=='ALL'&&record.kind!==state.readerKind)return false;const q=norm(state.readerQuery);if(!q)return true;const hay=norm(`${record.title} ${record.source} ${record.plain}`);return q.split(/\s+/).every(w=>hay.includes(w));}
function refreshReaderList(){const el=document.getElementById('readerList');if(!el||!activeDoc)return;const matches=activeDoc.records.filter(readerMatches);const selected=activeDoc.records.find(x=>x.key===state.selectedKey);if(!selected||!matches.includes(selected)){const first=matches.find(x=>x.kind==='IR'&&x.title)||matches.find(x=>x.title)||matches[0];state.selectedKey=first?.key||null;}document.getElementById('readerCount').textContent=matches.length.toLocaleString('tr-TR')+' kayıt';const items=matches.slice(0,state.readerLimit);el.innerHTML=items.map(rec=>`<button type="button" class="rule-row ${state.selectedKey===rec.key?'active':''}" data-open-rule="${esc(rec.key)}"><span class="rule-row-title"><span>${esc(short(displayTitle(rec),104))}</span>${pill(rec.kind)}</span><span class="rule-row-sub">${esc(short(rec.plain?.replace(/\s+/g,' '),120))}</span><span class="rule-row-path">${esc(short(rec.category,65))}</span></button>`).join('')+(matches.length>items.length?`<button class="load-more" data-action="more-reader">${(matches.length-items.length).toLocaleString('tr-TR')} kayıt daha · Daha fazla göster</button>`:'')||`<div class="empty-state">${icon('search')}<b>Sonuç bulunamadı</b>Filtreleri veya arama ifadenizi değiştirin.</div>`;refreshDetail();}
function refreshReaderSelection(){document.querySelectorAll('.rule-row').forEach(x=>x.classList.toggle('active',x.dataset.openRule===state.selectedKey));refreshDetail();}
function renderBlocks(blocks){if(!blocks?.length)return `<p class="muted">Metin bulunamadı.</p>`;return blocks.map(b=>{if('rows' in b)return `<div class="table-scroll"><table><tbody>${b.rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;return b.h?`<h4>${esc(b.t)}</h4>`:`<p>${esc(b.t)}</p>`;}).join('');}
function relatedRecords(doc,rec){if(!rec||!(rec.kind==='IR'||rec.kind==='DR'||rec.kind==='CS'))return [];const name=norm(rec.title),code=extractCode(rec.title),related=doc.records.filter(x=>x!==rec&&(x.kind==='AMC'||x.kind==='GM')&&(norm(x.parentIR)===name||(code&&norm(x.parentIR).startsWith(norm(code)+' '))));return related.slice(0,35);}
function refreshDetail(){const el=document.getElementById('readerDetail');if(!el||!activeDoc)return;const r=activeDoc.records.find(x=>x.key===state.selectedKey);if(!r){el.innerHTML='<div class="empty-state">Seçilecek kayıt bulunamadı.</div>';return;}const a=getAnnotation(activeDoc.familyId,r),related=relatedRecords(activeDoc,r);el.innerHTML=`<div class="detail-kicker">${pill(r.kind)}<span>${esc(r.path?.join(' › ')||r.category)}</span></div><h1>${esc(displayTitle(r))}</h1><div class="detail-desc">${esc(activeDoc.title)} · ${esc(slugDate(activeDoc.published))}</div><div class="detail-controls"><button class="btn small" data-action="toggle-bookmark">${icon('bookmark','sm')}${a.bookmarked?'Yer iminden çıkar':'Yer imlerine ekle'}</button><button class="btn small" data-action="copy-rule">${icon('copy','sm')}Metni kopyala</button><button class="btn small" data-action="download-rule">${icon('download','sm')}TXT indir</button><button class="btn small" data-action="print-rule">${icon('print','sm')}Yazdır</button><span class="text-id">ID: ${esc(r.erules||r.id)}</span></div><div class="detail-meta"><div class="detail-meta-box"><div class="detail-meta-label">Düzenleyici kaynak</div><div class="detail-meta-val">${esc(r.source||'Belirtilmemiş')}</div></div><div class="detail-meta-box"><div class="detail-meta-label">Uygulanabilirlik tarihi</div><div class="detail-meta-val">${esc(r.applicability||'Belirtilmemiş')}</div></div><div class="detail-meta-box"><div class="detail-meta-label">Yürürlüğe giriş</div><div class="detail-meta-val">${esc(r.effective||'Belirtilmemiş')}</div></div></div><div class="body-label">ORİJİNAL DÜZENLEME METNİ · EN</div><div class="legal-text" id="currentRuleText">${renderBlocks(r.blocks)}</div>${related.length?`<section class="related-wrap"><div class="body-label">BAĞLANTILI AMC / GM (${related.length})</div><div class="related-items">${related.map(x=>`<button class="related-link" data-open-rule="${esc(x.key)}">${pill(x.kind)}<span>${esc(displayTitle(x))}</span>${icon('chevron','sm')}</button>`).join('')}</div></section>`:''}<section class="notes-wrap"><div class="note-row">${icon('notebook')}<b>Bu maddeye ilişkin notlarım</b><span class="muted" style="margin-left:auto;font-size:10px">Sürümden bağımsız madde kimliğiyle saklanır</span></div><textarea class="form-field" id="ruleNote" placeholder="İnceleme notu, yorum veya takip edilmesi gereken hususlar…">${esc(a.note||'')}</textarea><div style="display:flex;justify-content:flex-end;align-items:center;gap:10px;margin-top:10px"><span id="noteStatus" class="inline-hint">${a.updatedAt?'Son kayıt: '+esc(shortDate(a.updatedAt)):''}</span>${btn('Notu kaydet','save-note','primary small','check')}</div></section><div class="info-strip" style="margin-top:20px">${icon('info')}<span>Bu kayıt ${esc(shortDate(activeDoc.published))} tarihli yüklenmiş konsolide XML yayınından alınmıştır. Hukuki uygulanabilirlik ve güncellik ayrıca ilgili resmî düzenlemelerden doğrulanmalıdır.</span></div>`;}
function renderSearchShell(){document.getElementById('screen').innerHTML=uiPage('Tüm mevzuatta ara','Birden fazla EASA yayınında madde kodu, kavram, düzenleme veya metin araması yapın.','ORTAK ARAMA MOTORU')+`<div class="panel"><div class="toolbar"><div class="form-search" style="flex:1;min-width:220px">${icon('search')}<input id="globalQuery" class="form-field" style="width:100%" placeholder="Örn. safety management, ERCS, ARO.GEN.305…" value="${esc(state.globalQuery)}" aria-label="Tüm mevzuatta ara" /></div><label class="sr-only" for="globalFamily">Yayın</label><select class="form-field" id="globalFamily"><option value="ALL">Tüm yayınlar</option>${familyRows.map(f=>`<option value="${esc(f.id)}" ${state.globalFamily===f.id?'selected':''}>${esc(short(f.title.replace('Easy Access Rules for ','') ,34))}</option>`).join('')}</select><label class="sr-only" for="globalKind">Kayıt türü</label><select class="form-field" id="globalKind">${['ALL','IR','DR','AMC','GM','CS','OTHER'].map(k=>`<option value="${k}" ${state.globalKind===k?'selected':''}>${k==='ALL'?'Tüm türler':k}</option>`).join('')}</select></div><div class="inline-hint" id="globalStatus">Yüklü aktif sürümlerde aranır. Arşivlenmiş sürümler karşılaştırma ekranındadır.</div></div><div id="globalResults" style="margin-top:15px"></div>`;runGlobalSearch().catch(showError);}
async function runGlobalSearch(){const el=document.getElementById('globalResults'),status=document.getElementById('globalStatus');if(!el)return;const q=norm(state.globalQuery);if(!q){el.innerHTML=`<div class="empty-state" style="background:#fff;border-radius:12px;border:1px solid var(--border)">${icon('search')}<b>Bir terim veya madde kodu yazın</b>Bulut kütüphanenizdeki kayıtlı yayınların etkin sürümlerinde arama yapabilirsiniz.</div>`;status.textContent='Arama yalnızca etkin seçili sürümlerde yapılır.';return;}const stamp=q+'|'+state.globalKind+'|'+state.globalFamily;state._searchStamp=stamp;status.textContent='Kütüphane taranıyor…';el.innerHTML='<div class="loading"><div><div class="spinner"></div>Sonuçlar hazırlanıyor…</div></div>';let results=[];const tokens=q.split(' ').filter(Boolean);for(const f of familyRows){if(state.globalFamily!=='ALL'&&f.id!==state.globalFamily)continue;let doc;try{doc=await getDoc(f.active);}catch(e){if(state._searchStamp!==stamp)return;status.textContent='Mevzuat verisi Drive’dan indirilemedi.';el.innerHTML=`<div class="empty-state">${icon('alert')}<b>Bulut dosyası okunamadı</b>${esc(e.message)}<div style="margin-top:12px">${btn('Drive bağla','drive','primary','cloud')}</div></div>`;return;}for(const rec of doc.records){if(state.globalKind!=='ALL'&&rec.kind!==state.globalKind)continue;const title=norm(displayTitle(rec)),body=norm(rec.plain),source=norm(rec.source);if(tokens.every(t=>title.includes(t)||body.includes(t)||source.includes(t))){const score=tokens.reduce((n,t)=>n+(title.includes(t)?20:0)+(norm(extractCode(rec.title)).includes(t)?10:0)+(source.includes(t)?5:0),0);results.push({familyId:f.id,releaseId:doc.versionId,title:displayTitle(rec),recordKey:rec.key,rec,docTitle:f.title,score});}}}
if(state._searchStamp!==stamp||state.view!=='search')return;results.sort((a,b)=>b.score-a.score||a.docTitle.localeCompare(b.docTitle)||a.title.localeCompare(b.title));state.searchMatches=results;status.textContent=results.length.toLocaleString('tr-TR')+' eşleşme · '+familyRows.length+' yayının seçili sürümleri';drawGlobalResults();}
function excerptWithQuery(text,query){const s=String(text||'').replace(/\s+/g,' ');const t=norm(query).split(' ')[0];const ix=norm(s).indexOf(t);const p=ix>=0?Math.max(0,ix-80):0;return (p>0?'…':'')+short(s.slice(p),260);}
function drawGlobalResults(){const el=document.getElementById('globalResults');if(!el)return;const arr=state.searchMatches||[];const shown=arr.slice(0,state.globalLimit);el.innerHTML=`<div class="global-results">${shown.map(x=>`<button class="result-card" data-global-open="${esc(x.familyId)}" data-record-key="${esc(x.recordKey)}" data-release-id="${esc(x.releaseId)}"><div class="result-row-top">${pill(x.rec.kind)}<span class="chip">${esc(short(x.docTitle.replace(/^Easy Access Rules for /i,''),50))}</span><span class="chip">${esc(short(x.rec.category,50))}</span></div><div class="result-title">${htmlHighlighted(x.title,state.globalQuery)}</div><div class="result-sub">${esc(x.rec.source||'EASA eRules')} · ${esc(shortDate(getReleaseMeta(x.releaseId)?.published))}</div><div class="result-snippet">${htmlHighlighted(excerptWithQuery(x.rec.plain,state.globalQuery),state.globalQuery)}</div></button>`).join('')||'<div class="empty-state">Eşleşme bulunamadı.</div>'}</div>${arr.length>shown.length?`<div style="text-align:center;margin-top:20px">${btn('Daha fazla sonuç göster ('+(arr.length-shown.length)+')','more-global','','plus')}</div>`:''}`;}
function renderBookmarks(){const anns=[...annotations.values()].filter(a=>a.bookmarked||a.note?.trim()).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));let rows=[];for(const a of anns){const [familyId,key]=a.id.split('::');const fam=getFamily(familyId);rows.push({a,fam,familyId,key});}document.getElementById('screen').innerHTML=uiPage('Yer imlerim ve notlarım','Sık başvurduğunuz hükümleri saklayın; her maddeye sürümlerden bağımsız inceleme notu ekleyin.','KİŞİSEL ÇALIŞMA ALANI')+`<div class="section-heading"><h2>${anns.length} kayıt</h2><span class="hint">${pinnedCount()} yer imi</span></div><div class="global-results">${rows.map(({a,fam,familyId,key})=>`<div class="result-card" style="cursor:default"><div class="result-row-top"><span class="chip ${a.bookmarked?'teal':''}">${icon('bookmark','sm')} ${a.bookmarked?'Yer imi':'Not'}</span><span class="chip">${esc(fam?.title||'Kütüphaneden kaldırılmış yayın')}</span></div><div class="result-title">${esc(a.title||key.replace(/^e:/,''))}</div>${a.note?.trim()?`<div class="result-snippet" style="white-space:pre-wrap">${esc(short(a.note,400))}</div>`:''}<div class="pub-bottom" style="margin-top:10px"><span>Güncelleme: ${esc(shortDate(a.updatedAt))}</span>${fam?`<button class="btn small" data-open-annotation="${esc(familyId)}" data-record-key="${esc(key)}">Maddeye git ${icon('chevron','sm')}</button>`:'<span class="chip amber">Yayın bulunamadı</span>'}</div></div>`).join('')||`<div class="panel"><div class="empty-state">${icon('bookmark')}<b>Henüz kayıt yok</b>Bir mevzuat maddesinin içinden yer imi ekleyebilir veya not yazabilirsiniz.</div></div>`}</div>`;}
function renderVersions(){const groups=familyRows.map(f=>`<div class="version-group"><div class="version-group-header"><div><h3>${esc(f.title)}</h3><div class="sub">${f.releases.length} arşivlenmiş sürüm · ${f.releases[0]?.count.toLocaleString('tr-TR')} kayıt (en yeni)</div></div><div class="page-actions"><button class="btn small" data-compare-family="${esc(f.id)}">${icon('compare','sm')} Karşılaştır</button><button class="btn primary small" data-open-family="${esc(f.id)}">${icon('file','sm')} Aç</button></div></div><div class="version-group-body table-scroll"><table class="data-table"><thead><tr><th>Yayın tarihi</th><th>Madde sayısı</th><th>Durum</th><th>İşlemler</th></tr></thead><tbody>${f.releases.map(r=>`<tr><td><b>${esc(shortDate(r.published))}</b><div class="inline-hint">${esc(short(r.guid||'',30))}</div></td><td>${r.count.toLocaleString('tr-TR')}</td><td>${r.versionId===f.active?'<span class="chip green">Aktif sürüm</span>':'<span class="chip">Arşiv</span>'}</td><td><div class="row-buttons"><button class="btn small" data-open-release="${esc(r.versionId)}" data-family-id="${esc(f.id)}">Görüntüle</button>${r.versionId!==f.active?`<button class="btn small" data-activate-release="${esc(r.versionId)}" data-family-id="${esc(f.id)}">Aktif yap</button>`:''}<button class="btn small" data-download-raw="${esc(r.versionId)}" title="Orijinal XML dosyasını Drive'dan indir">XML indir</button><button class="btn small danger" data-remove-release="${esc(r.versionId)}" aria-label="Sürümü sil">${icon('trash','sm')}</button></div></td></tr>`).join('')}</tbody></table></div></div>`).join('');document.getElementById('screen').innerHTML=uiPage('Sürüm yönetimi','Her mevzuat ailesinin sürümlerini ayrı saklayın; yeni ve eski metinleri karşılaştırın.','MEVZUAT ARŞİVİ',btn('Yeni XML yükle','upload','primary','upload')+btn('Katalog yedeği','backup','','download'))+`${groups||'<div class="panel">Henüz bir mevzuat sürümü bulunamadı.</div>'}<div class="info-strip">${icon('info')}<div>Yeni XML yüklendiğinde yayın kimliği üzerinden ait olduğu mevzuat ailesine eklenir. Tarihi daha yeni olan sürüm varsayılan olarak aktif olur. Sürümler arasındaki değişiklikler metin/metadata düzeyinde hesaplanır; hukuki yorum içermez.</div></div>`;}
function renderCompareShell(){const f=getFamily(state.diffFamily);if(!f){nav('versions');return;}if(!state.diffNew)state.diffNew=f.releases[0]?.versionId;if(!state.diffOld)state.diffOld=f.releases[1]?.versionId||f.releases[0]?.versionId;const options=(sel)=>f.releases.map(r=>`<option value="${esc(r.versionId)}" ${r.versionId===sel?'selected':''}>${esc(shortDate(r.published))}</option>`).join('');document.getElementById('screen').innerHTML=uiPage('Sürüm karşılaştırması',esc(f.title),'DEĞİŞİKLİK ANALİZİ',btn('Sürüm listesine dön','go-versions','','back'))+`<div class="panel"><div class="toolbar"><div><label class="inline-hint" for="diffOld">Eski sürüm</label><select class="form-field" id="diffOld" style="min-width:225px">${options(state.diffOld)}</select></div>${icon('compare','lg')}<div><label class="inline-hint" for="diffNew">Yeni sürüm</label><select class="form-field" id="diffNew" style="min-width:225px">${options(state.diffNew)}</select></div>${btn('Karşılaştır','start-compare','primary','compare')}</div><div class="inline-hint">Eşleştirmede EASA ERulesId kimliği, gerektiğinde düzenleyici kaynak ve başlık birlikte kullanılır. Değişen kayıtların tarih veya kaynak metaverileri de karşılaştırılır.</div></div><div id="compareResults"></div>`;if(state.diffRows.length)drawCompareResults();}
function naturalRecordKey(r){return norm([r.category,r.source,r.path?.join('>'),r.title].join('|'));}
function compareDocs(oldDoc,newDoc){const oldById=new Map(oldDoc.records.map((r,i)=>[r.key,{r,i}]));const newById=new Map(newDoc.records.map((r,i)=>[r.key,{r,i}]));const newNatural=new Map();newDoc.records.forEach((r,i)=>{const k=naturalRecordKey(r);if(!newNatural.has(k))newNatural.set(k,[]);newNatural.get(k).push({r,i});});const visited=new Set(),rows=[];const contentKey=r=>JSON.stringify([r.title,r.plain,r.kind,r.source,r.applicability,r.effective,r.category,r.path]);
for(const old of oldDoc.records){let newEntry=newById.get(old.key);if(!newEntry||visited.has(newEntry.i)){newEntry=(newNatural.get(naturalRecordKey(old))||[]).find(e=>!visited.has(e.i));}if(newEntry){visited.add(newEntry.i);const newRec=newEntry.r;const status=contentKey(old)===contentKey(newRec)?'unchanged':'changed';rows.push({status,old,new:newRec,title:displayTitle(newRec),category:newRec.category});}else rows.push({status:'removed',old,new:null,title:displayTitle(old),category:old.category});}
newDoc.records.forEach((r,i)=>{if(!visited.has(i))rows.push({status:'added',old:null,new:r,title:displayTitle(r),category:r.category});});return rows;}
async function runCompare(){if(state.diffOld===state.diffNew){showToast('Karşılaştırmak için iki farklı sürüm seçin.','warn');return;}const el=document.getElementById('compareResults');el.innerHTML='<div class="loading"><div><div class="spinner"></div>Sürümler karşılaştırılıyor…</div></div>';const [oldDoc,newDoc]=await Promise.all([getDoc(state.diffOld),getDoc(state.diffNew)]);state.diffRows=compareDocs(oldDoc,newDoc);state.diffSelected=state.diffRows.findIndex(r=>r.status==='changed');if(state.diffSelected<0)state.diffSelected=state.diffRows.findIndex(r=>r.status!=='unchanged');if(state.diffSelected<0)state.diffSelected=0;state.diffFilter='CHANGES';drawCompareResults();}
const STATUS_LABEL={added:'Eklendi',removed:'Kaldırıldı',changed:'Değişti',unchanged:'Aynı'};
function statusPill(s){const classes={added:'green',removed:'red',changed:'amber',unchanged:''};return `<span class="chip ${classes[s]}">${STATUS_LABEL[s]}</span>`;}
function drawCompareResults(){const el=document.getElementById('compareResults');if(!el)return;const stats={added:0,removed:0,changed:0,unchanged:0};state.diffRows.forEach(r=>stats[r.status]++);const filters=['CHANGES','changed','added','removed','unchanged','ALL'];const filterText={CHANGES:'Yalnızca farklı',ALL:'Tümü',changed:'Değişen',added:'Eklenen',removed:'Kaldırılan',unchanged:'Aynı'};el.innerHTML=`<div class="section-heading"><h2>Karşılaştırma sonuçları</h2><div class="compare-stats">${statusPill('added')} ${stats.added} ${statusPill('removed')} ${stats.removed} ${statusPill('changed')} ${stats.changed} <span class="chip">Aynı ${stats.unchanged}</span></div></div><div class="toolbar">${filters.map(f=>`<button class="filter-chip ${state.diffFilter===f?'active':''}" data-diff-filter="${f}">${filterText[f]}</button>`).join('')}</div><div class="diff-layout"><div class="diff-list" id="diffItems"></div><div class="diff-preview" id="diffPreview"></div></div>`;drawDiffList();}
function visibleDiffIndexes(){return state.diffRows.map((r,i)=>({...r,i})).filter(r=>state.diffFilter==='ALL'||state.diffFilter==='CHANGES'&&r.status!=='unchanged'||r.status===state.diffFilter);}
function drawDiffList(){const el=document.getElementById('diffItems');if(!el)return;const rows=visibleDiffIndexes();if(rows.length&&!rows.some(r=>r.i===state.diffSelected))state.diffSelected=rows[0].i;el.innerHTML=rows.slice(0,800).map(r=>`<button class="diff-item ${r.i===state.diffSelected?'active':''}" data-diff-index="${r.i}"><div style="display:flex;gap:8px;align-items:center;justify-content:space-between"><b>${esc(short(r.title,98))}</b>${statusPill(r.status)}</div><small>${esc(short(r.category,75))}</small></button>`).join('')+(rows.length>800?'<div class="inline-hint" style="padding:12px">İlk 800 kayıt gösteriliyor; filtreyi daraltın.</div>':'')||'<div class="empty-state">Bu filtrede farklı kayıt yok.</div>';drawDiffPreview();}
function diffMarked(oldTxt,newTxt,isOld){if(!oldTxt&&!newTxt)return '';if(!oldTxt)return esc(newTxt);if(!newTxt)return esc(oldTxt);const a=String(oldTxt),b=String(newTxt),limit=Math.min(a.length,b.length);let start=0;while(start<limit&&a[start]===b[start])start++;let endA=a.length-1,endB=b.length-1;while(endA>=start&&endB>=start&&a[endA]===b[endB]){endA--;endB--;}const t=isOld?a:b,stop=isOld?endA:endB;return esc(t.slice(0,start))+(isOld?'<del>':'<ins>')+esc(t.slice(start,stop+1))+(isOld?'</del>':'</ins>')+esc(t.slice(stop+1));}
function drawDiffPreview(){const el=document.getElementById('diffPreview');if(!el)return;const row=state.diffRows[state.diffSelected];if(!row){el.innerHTML='<div class="empty-state">Karşılaştırılacak kayıt bulunamadı.</div>';return;}let oldTxt=row.old?.plain||'',newTxt=row.new?.plain||'';el.innerHTML=`<div class="result-row-top">${statusPill(row.status)} ${row.new?pill(row.new.kind):row.old?pill(row.old.kind):''}</div><h3 class="compact-head">${esc(row.title)}</h3><div class="inline-hint" style="margin-bottom:16px">${esc(row.category)} · ${esc(row.new?.source||row.old?.source||'EASA')}</div><div class="comparison-columns"><div class="comparison-pane"><header>${icon('history','sm')} ESKİ SÜRÜM · ${esc(shortDate(getReleaseMeta(state.diffOld)?.published))}</header><div class="diff-text">${row.old?diffMarked(oldTxt,newTxt,true):'<i>Bu sürümde kayıt yok.</i>'}</div><div class="inline-hint" style="margin-top:13px">Uygulanabilirlik: ${esc(row.old?.applicability||'—')}</div></div><div class="comparison-pane"><header>${icon('file','sm')} YENİ SÜRÜM · ${esc(shortDate(getReleaseMeta(state.diffNew)?.published))}</header><div class="diff-text">${row.new?diffMarked(oldTxt,newTxt,false):'<i>Bu sürümde kayıt yok.</i>'}</div><div class="inline-hint" style="margin-top:13px">Uygulanabilirlik: ${esc(row.new?.applicability||'—')}</div></div></div><div class="info-strip" style="margin-top:16px">${icon('info')}<span>İşaretli alanlar iki XML sürümü arasındaki metin farkını gösterir. Yalnızca madde numarası veya içeriğin değişmesi mevzuatın mutlaka yürürlüğe girdiği anlamına gelmez.</span></div>`;}
function renderSettings(){
  const status=cloudConfigStatus(),cfg=status.config;
  const configured=EasaCloud.configured(cfg),u=EasaCloud.user();
  const fields=[['apiKey','Firebase API Key'],['authDomain','Auth Domain'],['projectId','Project ID'],['appId','App ID']]
    .map(([k,title])=>`<label class="cloud-label">${title}<input class="form-field" name="${k}" value="${esc(cfg[k]||'')}" placeholder="${esc(k==='authDomain'?'proje.firebaseapp.com':k)}" autocomplete="off" required></label>`).join('');
  // Keep the config export action visible regardless of whether settings are
  // supplied by GitHub (published) or by the existing browser (local).
  const configActions=configured
    ? btn('config.js indir','export-config','primary','download') + btn('Kodunu kopyala','copy-config','','copy')
    : '';
  const common=uiPage('Hesap ve bağlantı','Google hesabınızla giriş yapın; mevzuatlarınız Firebase ve Google Drive üzerinden cihazlar arasında senkronize edilir.','BULUT HESABI',configActions);
  const setup=status.source==='published'?`
    <div class="section-heading"><h2>Firebase bağlantısı</h2><span class="chip green">GitHub üzerinden otomatik</span></div>
    <div class="config-success">${icon('check','lg')}<div><b>Hazır: bu cihazda Firebase bilgisi girmenize gerek yok.</b><br>
    <span>Proje: <code>${esc(cfg.projectId)}</code> · Kaynak: <code>config.js</code></span><br>
    <span>Farklı bir telefonda ya da bilgisayarda aynı GitHub Pages adresini açıp Google hesabınızla giriş yapabilirsiniz. Bu durumda config.js dosyasını yeniden yüklemeniz gerekmez; üstteki "config.js indir" düğmesi isteğe bağlı yedek almak içindir.</span></div></div>
    ${status.different?`<div class="info-strip">${icon('info')}<div>Bu cihazda eski bir yerel proje ayarı da var. GitHub'daki yapılandırma öncelikli kullanılır. Geçerli proje <b>${esc(cfg.projectId)}</b>; yerel ayarlar veri silinmeden korunur.</div></div>`:''}
    <details class="advanced-config"><summary>Teknik bağlantı bilgileri</summary><p>Firebase Project ID: <code>${esc(cfg.projectId)}</code><br>
    Auth Domain: <code>${esc(cfg.authDomain)}</code></p><p>Bu bilgileri değiştirmek isterseniz GitHub deposunun kök dizinindeki <code>config.js</code> dosyasını güncelleyin. API anahtarlarını ve App ID'yi her cihazda tekrar girmeniz gerekmez.</p></details>`:
    status.source==='local'?`
    <div class="section-heading"><h2>Tek seferlik cihazlar arası kurulum</h2><span class="chip amber">Yalnızca bu cihazda kayıtlı</span></div>
    <p>Firebase bağlantınız <b>${esc(cfg.projectId)}</b> projesine çalışıyor, ancak bilgiler henüz GitHub Pages üzerinden paylaşılmıyor. Telefonunuzun aynı ayarları otomatik alması için aşağıdaki işlemi <b>bir kez</b> yapmanız yeterli.</p>
    <div class="setup-steps"><div><b>1</b><span>Bu bilgisayardan <strong>config.js indir</strong> düğmesine basın. Dosya mevcut çalışan Firebase ayarlarınızı içerir.</span></div>
    <div><b>2</b><span>GitHub deposunun <strong>kök dizinindeki config.js</strong> dosyasını indirdiğiniz dosyayla değiştirip kaydedin. <code>src/</code> içine koymayın.</span></div>
    <div><b>3</b><span>GitHub Pages güncellendikten sonra telefondan aynı adresi açın. Artık yalnızca <strong>Google ile giriş</strong> yapmanız gerekir.</span></div></div>
    <p class="inline-hint">Üstteki <strong>config.js indir</strong> düğmesi mevcut tarayıcı ayarlarınızdan dosyayı oluşturur; alternatif olarak <strong>Kodunu kopyala</strong> seçeneğini kullanabilirsiniz.</p>
    <p class="inline-hint">Firebase Web App yapılandırması gizli sunucu anahtarı değildir. Ancak Google OAuth client secret, erişim belirteci, parola veya servis hesabı anahtarı bu dosyaya eklenmemelidir.</p>
    <details class="advanced-config"><summary>Gelişmiş: bu cihazdaki Firebase bilgilerini düzenle</summary><form id="firebaseForm" class="cloud-form">${fields}<button class="btn primary" type="submit">Bu cihazda kaydet</button></form><p class="inline-hint">Bu alanlar yalnızca bu tarayıcıda saklanır. Diğer cihazlarda tekrar girmemek için yukarıdaki config.js aktarımını tamamlayın.</p></details>`:`
    <div class="section-heading"><h2>İlk bağlantı kurulumu</h2><span class="chip amber">Yapılandırma bulunamadı</span></div>
    <p>Bu cihaz henüz paylaşılan <code>config.js</code> dosyasını alamadı. Kütüphanenin daha önce çalıştığı <b>bilgisayardan</b> <strong>Hesap ve bağlantı → config.js indir</strong> adımını uygulayın ve dosyayı GitHub depo köküne yükleyin. Sonrasında bu cihazda ayar girmenize gerek kalmayacak.</p>
    <details class="advanced-config"><summary>Alternatif: ilk kurulumu bu cihazda manuel yap</summary><p class="muted">Firebase Console → Project settings → Your apps → Web app bölümünden Web App bilgilerini girebilirsiniz. Bu işlem yalnızca bu cihaz içindir.</p><form id="firebaseForm" class="cloud-form">${fields}<button class="btn primary" type="submit">Bu cihazda kaydet</button></form></details>`;
  document.getElementById('screen').innerHTML=common+`
    <div class="setting-grid">
    <section class="panel"><div class="pub-icon">${icon('cloud')}</div><h3>Google hesabı ve Drive</h3>
      <p>${u?'Oturum: <b>'+esc(u.email||u.uid)+'</b>':'Henüz Google hesabıyla giriş yapılmadı.'}</p>
      <p>Drive: <b>${EasaCloud.driveReady()?'Bağlı':'Bağlantı bekliyor'}</b>. Güvenlik nedeniyle Drive yetkisi gerektiğinde yeniden alınabilir.</p>
      <div class="settings-actions">${configured?btn(u?'Drive erişimini yenile':'Google ile giriş','signin','primary','cloud'):btn('İlk bağlantı kurulumu','go-settings','','settings')}${u?btn('Drive klasörünü aç','open-drive','','external'):''}</div></section>
    <section class="panel"><div class="pub-icon">${icon('download')}</div><h3>Katalog yedeği</h3>
      <p>Mevzuat kataloğunu, notlarınızı ve yer imlerinizi JSON olarak indirir. <b>Orijinal XML dosyaları Drive'da kalır.</b></p>
      ${btn('Katalog yedeğini indir','backup','primary','download')}${u?btn('Notları yedekten aktar','restore','','upload'):''}</section>
    <section class="panel"><div class="pub-icon">${icon('settings')}</div><h3>Yerel önbellek</h3>
      <p>${persistent?'Okunan mevzuatlar bu cihazda IndexedDB ile önbelleğe alınır.':'IndexedDB kullanılamıyor; okumak için Drive bağlantısı gerekebilir.'}</p>
      <span class="chip ${persistent?'green':'amber'}">${persistent?'Önbellek hazır':'Önbellek kapalı'}</span></section>
    <section class="panel"><div class="pub-icon">${icon('info')}</div><h3>Mevzuat kaynağı</h3>
      <p>Yalnızca yüklediğiniz EASA eRules XML dosyaları gösterilir; yayımlanma ve uygulanabilirlik tarihleri ayrı izlenir.</p><span class="chip">v3.3.1 · GitHub + Firebase + Drive</span></section></div>
    <section class="panel cloud-config-panel">${setup}</section>
    <div class="info-strip">${icon('info')}<div>Orijinal XML'leriniz Google Drive'da, mevzuat kayıtları ve notlarınız Firebase'de saklanır. Bu güncelleme mevcut verileri taşımaz veya silmez. Firebase bağlantı bilgileri herkese açık GitHub Pages üzerinden paylaşılacağı için erişim güvenliği Firestore kuralları ve Google hesap izinleriyle sağlanmalıdır.</div></div>`;
}

async function renderScreen(){document.getElementById('breadcrumbs').innerHTML=breadcrumb();updateSidebar();switch(state.view){case 'library':initLibrary();break;case 'reader':await renderReader();break;case 'search':renderSearchShell();break;case 'bookmarks':renderBookmarks();break;case 'versions':renderVersions();break;case 'compare':renderCompareShell();break;case 'settings':renderSettings();break;default:initLibrary();}}
function parseFile(file,onProgress){return new Promise(async(resolve,reject)=>{let worker=null,src=null;try{if(window.EASA_PARSER_WORKER_SOURCE){src=URL.createObjectURL(new Blob([window.EASA_PARSER_WORKER_SOURCE],{type:'text/javascript'}));worker=new Worker(src);}else worker=new Worker(new URL('./src/parser.worker.js',document.baseURI));worker.onmessage=e=>{const v=e.data;if(v.type==='progress')onProgress?.(v.percent,v.label);else if(v.type==='success'){worker.terminate();if(src)URL.revokeObjectURL(src);resolve(v.doc);}else if(v.type==='error'){worker.terminate();if(src)URL.revokeObjectURL(src);reject(new Error(v.message));}};worker.onerror=e=>{worker.terminate();if(src)URL.revokeObjectURL(src);reject(Error('XML işleyici hatası: '+e.message));};worker.postMessage({file});}catch(err){if(worker)worker.terminate();if(src)URL.revokeObjectURL(src);try{const doc=parseEasaXml(await file.text(),onProgress);resolve(doc);}catch(error){reject(error);}}});}
async function importFiles(files){if(!files?.length)return;if(!EasaCloud.user())throw Error('XML yüklemek için Google hesabınızla oturum açın.');if(!EasaCloud.driveReady())throw Error('Önce Drive bağla ile Google Drive erişimini etkinleştirin.');const list=[...files].filter(f=>/\.xml$/i.test(f.name));if(!list.length)throw Error('XML (.xml) dosyası seçin.');modal(`<h2>${icon('upload')} XML dosyaları buluta aktarılıyor</h2><p id="progressLabel">Dosyalar kontrol ediliyor…</p><div class="progress-track"><div class="progress-fill" id="progressFill"></div></div><div class="inline-hint" id="progressCount">0 / ${list.length}</div>`,true);const errors=[],added=[],skipped=[];for(let i=0;i<list.length;i++){const f=list[i],label=document.getElementById('progressLabel'),bar=document.getElementById('progressFill'),count=document.getElementById('progressCount');count.textContent=`${i+1} / ${list.length} dosya`;try{if(f.size>280*1024*1024)throw Error('Dosya 280 MB sınırını aşıyor.');const doc=await parseFile(f,(pct,txt)=>{label.textContent=short(f.name,54)+' · '+txt;bar.style.width=(((i+(pct*.40)/100)/list.length)*100)+'%';});if(releaseRows.some(r=>r.versionId===doc.versionId)){skipped.push(doc.title+' ('+shortDate(doc.published)+')');continue;}label.textContent='Sıkıştırılıyor: '+short(f.name,52);const {binary,compressed}=await compressJson(doc);const meta=await EasaCloud.uploadVersion(doc,f,binary,compressed,(pct,txt)=>{label.textContent=short(f.name,50)+' · '+txt;bar.style.width=(((i+0.40+pct*.60/100)/list.length)*100)+'%';});const key=EasaCloud.user().uid+'|'+doc.versionId;try{await storePut('releases',{...rowForDoc(doc,binary,compressed,meta),versionId:key});}catch(e){console.warn('İçe aktarma önbelleğe yazılamadı:',e);}cache.set(key,doc);const previous=getFamily(doc.familyId);if(!previous||String(doc.published)>String(previous.current?.published))await EasaCloud.saveActive(doc.familyId,doc.versionId);added.push(doc.title+' ('+shortDate(doc.published)+')');releaseRows.push(meta);buildFamilies();}catch(err){errors.push(f.name+': '+(err.message||String(err)));}finally{bar.style.width=(((i+1)/list.length)*100)+'%';}}await refreshMetadata();modalLocked=false;closeModal();if(added.length)showToast(added.length+' XML sürümü Google Drive ve Firebase’e kaydedildi.');if(skipped.length)showToast(skipped.length+' sürüm zaten bulutta kayıtlı.','warn');if(errors.length)modal(`<h2>${icon('alert')} Yükleme uyarıları</h2><p>${errors.map(s=>esc(s)).join('<br>')}</p><div class="modal-actions">${btn('Kapat','close-modal','primary')}</div>`);if(state.view==='reader'&&state.familyId&&getFamily(state.familyId)){state.releaseId=activeMeta(state.familyId).versionId;state.selectedKey=null;}if(state.view==='compare')state.diffRows=[];await renderScreen();}


async function exportBackup(){if(!EasaCloud.user())throw Error('Önce bulut hesabına giriş yapın.');const data={format:'easa-erules-cloud-manifest',schema:3,createdAt:new Date().toISOString(),uid:EasaCloud.user().uid,releases:releaseRows.map(({stats,...r})=>({...r,stats})),annotations:[...annotations.values()],active:Object.fromEntries([...settings].filter(([k])=>k.startsWith('active:')))};saveFile(`EASA_Bulut_Katalog_Yedek_${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(data,null,2),'application/json;charset=utf-8');showToast('Katalog ve not yedeği indirildi. Orijinal XML dosyaları Drive’da kalır.');}
async function restoreBackup(file){if(!file)return;if(!EasaCloud.user())throw Error('Önce bulut hesabına giriş yapın.');if(file.size>30*1024*1024)throw Error('Katalog yedeği 30 MB sınırını aşıyor.');const data=JSON.parse(await file.text());if(data.format!=='easa-erules-cloud-manifest'||data.schema!==3)throw Error('Yalnızca v3 katalog yedeği destekleniyor. XML verisi içeren v2 yedeklerini doğrudan buluta aktaramazsınız.');if(data.uid!==EasaCloud.user().uid)throw Error('Bu yedek farklı bir kullanıcı hesabına ait.');const ann=Array.isArray(data.annotations)?data.annotations:[];if(!confirm(`${ann.length} not/yer imi bulut kataloğunuza birleştirilecek. Devam edilsin mi?`))return;let count=0;for(const a of ann){if(!a?.id||typeof a.id!=='string')continue;const old=annotations.get(a.id);if(!old||String(a.updatedAt||'')>String(old.updatedAt||'')){await EasaCloud.saveAnnotation(a);count++;}}const active=data.active||{};for(const [key,id] of Object.entries(active)){const family=key.startsWith('active:')?key.slice(7):null;if(family&&getFamily(family)?.releases.some(r=>r.versionId===id))await EasaCloud.saveActive(family,id);}await refreshMetadata();await renderScreen();showToast(count+' not/yer imi buluta aktarıldı.');}
async function removeRelease(id){const meta=getReleaseMeta(id);if(!meta)return;if(!EasaCloud.driveReady())throw Error('Silme işlemi için Google Drive bağlantısı gereklidir.');const title=`${meta.title} – ${shortDate(meta.published)}`;if(!confirm(`DİKKAT: Bu sürüm Firebase kataloğundan ve Google Drive'dan kalıcı olarak silinecek!\n\n${title}\n\nDiğer sürümler korunur. Bu işlem geri alınamaz. Devam edilsin mi?`))return;const result=await EasaCloud.removeVersion(meta);const key=EasaCloud.user().uid+'|'+id;await storeDel('releases',key);cache.delete(key);await refreshMetadata();if(state.view==='reader'&&state.releaseId===id){state.familyId=getFamily(meta.familyId)?.id||null;state.releaseId=state.familyId?getFamily(state.familyId).active:null;if(!state.familyId)state.view='library';}showToast(result.orphaned?'Katalogdan silindi; Drive’da bazı artık dosyalar kalmış olabilir.':'Sürüm ve orijinal XML buluttan silindi.',result.orphaned?'warn':'');await renderScreen();}
function selectedRecord(){return activeDoc?.records.find(r=>r.key===state.selectedKey);}
async function toggleBookmark(){const r=selectedRecord();if(!r)return;const id=annotId(activeDoc.familyId,r);const before=getAnnotation(activeDoc.familyId,r);await updateAnnotation(id,{bookmarked:!before.bookmarked,title:displayTitle(r)});refreshDetail();showToast(!before.bookmarked?'Madde yer imlerine eklendi.':'Yer imi kaldırıldı.');}
async function saveNote(){const r=selectedRecord(),textarea=document.getElementById('ruleNote');if(!r||!textarea)return;const id=annotId(activeDoc.familyId,r);await updateAnnotation(id,{note:textarea.value,title:displayTitle(r)});const hint=document.getElementById('noteStatus');if(hint)hint.textContent='Kaydedildi · '+shortDate(new Date().toISOString());showToast('Madde notu kaydedildi.');}
function recordText(r){return `${displayTitle(r)}\nKaynak: ${r.source||'EASA eRules'}\nYayın: ${activeDoc.title} (${shortDate(activeDoc.published)})\n\n${r.plain||''}`;}
async function copyRecord(){const r=selectedRecord();if(!r)return;const text=recordText(r);try{await navigator.clipboard.writeText(text);showToast('Madde metni panoya kopyalandı.');}catch{const area=document.createElement('textarea');area.value=text;document.body.appendChild(area);area.select();const ok=document.execCommand('copy');area.remove();showToast(ok?'Madde metni kopyalandı.':'Kopyalama kısıtlı: TXT indir seçeneğini kullanın.',ok?'':'warn');}}
function downloadRecord(){const r=selectedRecord();if(!r)return;saveFile(safeFilename(displayTitle(r))+'.txt',recordText(r));}

// v3.3: Keep the v3 localStorage key for a lossless migration from v3.2.
// A valid public config.js always takes priority on all devices; old local settings
// remain available as a fallback until the owner publishes the shared config.
const CLOUD_SETTINGS_KEY='easa-cloud-firebase-config-v3';
function localCloudConfig(){
  try {const cfg=JSON.parse(localStorage.getItem(CLOUD_SETTINGS_KEY)||'null');return EasaCloud.configured(cfg)?cfg:null;}
  catch {return null;}
}
function cloudConfigStatus(){
  const published=EasaCloud.configured(window.EASA_CONFIG)?window.EASA_CONFIG:null;
  const local=localCloudConfig();
  const config=published||local||{};
  return {config,source:published?'published':local?'local':'missing',published,local,
    different:!!(published&&local&&['apiKey','authDomain','projectId','appId'].some(k=>published[k]!==local[k]))};
}
function readCloudConfig(){return cloudConfigStatus().config;}
function sharedConfigText(cfg){
  if(!EasaCloud.configured(cfg))throw Error('Önce bu bilgisayarda geçerli Firebase bağlantısı bulunmalıdır.');
  // Firebase Web App identifiers are public client-side configuration. Never
  // export OAuth tokens, passwords, OAuth client secrets or service-account keys.
  const publicConfig=Object.fromEntries(['apiKey','authDomain','projectId','appId'].map(k=>[k,String(cfg[k]).trim()]));
  return '/* EASA eRules Hub v3.3.1 - paylaşılan Firebase Web App ayarları.\n'+
    '   GitHub Pages repo köküne config.js adıyla yükleyin.\n'+
    '   Bu dosyaya OAuth client secret, erişim belirteci veya servis hesabı anahtarı koymayın.\n*/\n'+
    'window.EASA_CONFIG = '+JSON.stringify(publicConfig,null,2)+';\n';
}
function exportSharedConfig(){
  const {config}=cloudConfigStatus();
  if(!EasaCloud.configured(config))throw Error('Bu cihazda Firebase ayarları bulunmuyor. Hâlihazırda giriş yaptığınız bilgisayardan tekrar deneyin.');
  saveFile('config.js',sharedConfigText(config),'application/javascript;charset=utf-8');
  showToast('config.js indirildi. GitHub deposunun kök dizinindeki config.js dosyasını bununla değiştirin.');
}
async function copySharedConfig(){
  const content=sharedConfigText(readCloudConfig());
  if(!navigator.clipboard?.writeText)throw Error('Bu tarayıcıda panoya kopyalama desteklenmiyor. config.js indir seçeneğini kullanın.');
  await navigator.clipboard.writeText(content);
  showToast('Firebase yapılandırması kopyalandı. GitHub’da config.js dosyasına yapıştırıp kaydedin.');
}
async function saveCloudConfig(data){
  const cfg={apiKey:String(data.apiKey||'').trim(),authDomain:String(data.authDomain||'').trim(),projectId:String(data.projectId||'').trim(),appId:String(data.appId||'').trim()};
  if(!EasaCloud.configured(cfg))throw Error('Firebase yapılandırmasında eksik veya geçersiz alan var.');
  if(EasaCloud.configured(window.EASA_CONFIG))throw Error('GitHub üzerinden paylaşılan Firebase ayarları etkin. Projeyi değiştirmek için GitHub\'daki config.js dosyasını düzenleyin.');
  localStorage.setItem(CLOUD_SETTINGS_KEY,JSON.stringify(cfg));
  showToast('Firebase ayarları bu tarayıcıya kaydedildi. Uygulama yeniden başlatılıyor.');
  location.reload();
}

async function syncCloud(){if(syncPromise)return syncPromise;syncPromise=(async()=>{cache.clear();activeDoc=null;state.view='library';state.familyId=null;state.releaseId=null;await refreshMetadata();await renderScreen();})();try{return await syncPromise;}finally{syncPromise=null;}}
async function handleCloudUserChange(){try{await syncCloud();}catch(e){showError(e);}}
async function connectGoogle(){if(cloudStarting)return;cloudStarting=true;try{if(!cloudConnected){const cfg=readCloudConfig();if(!EasaCloud.configured(cfg)){nav('settings');throw Error('Önce GitHub üzerinde config.js bağlantısını yayımlayın veya Hesap ve bağlantı bölümünden ilk kurulumu yapın.');}await EasaCloud.init(cfg,handleCloudUserChange);cloudConnected=true;}await EasaCloud.signIn();await syncCloud();showToast('Google hesabı bağlandı; Drive dosya erişim izni doğrulandı.');}finally{cloudStarting=false;updateSidebar();}}
async function disconnectGoogle(){await EasaCloud.signOut();cache.clear();await syncCloud();showToast('Oturum kapatıldı. Bulut verileri korunur.');}
async function openDriveFolder(){if(!EasaCloud.driveReady())throw Error('Önce Drive hesabınızı bağlayın.');const folders=await EasaCloud.getOrCreateFolders();const url=await EasaCloud.getFolderUrl();if(!url)throw Error('Drive klasör bağlantısı bulunamadı.');window.open(url,'_blank','noopener,noreferrer');}
async function downloadOriginalXml(id){const row=getReleaseMeta(id);if(!row?.rawFileId)throw Error('Bu sürümün orijinal XML dosyası bulunamadı.');const data=await EasaCloud.getXmlFile(row.rawFileId);saveFile(row.rawName||'easa-original.xml',data,'application/xml');showToast('Orijinal XML indirildi.');}

function handleAction(action){switch(action){case 'upload':if(!EasaCloud.user())return nav('settings');if(!EasaCloud.driveReady())return showToast('XML yüklemek için önce Drive bağla.','warn');document.getElementById('xmlFiles').click();break;case 'restore':document.getElementById('backupFile').click();break;case 'backup':exportBackup().catch(showError);break;case 'export-config':try{exportSharedConfig();}catch(e){showError(e);}break;case 'copy-config':copySharedConfig().catch(showError);break;case 'sync-cloud':syncCloud().then(()=>showToast('Bulut kataloğu güncellendi.')).catch(showError);break;case 'signin':connectGoogle().catch(showError);break;case 'drive':closeModal();connectGoogle().catch(showError);break;case 'signout':disconnectGoogle().catch(showError);break;case 'open-drive':openDriveFolder().catch(showError);break;case 'go-search':nav('search');break;case 'go-library':nav('library');break;case 'go-versions':nav('versions');break;case 'go-settings':nav('settings');break;case 'more-reader':state.readerLimit+=90;refreshReaderList();break;case 'more-global':state.globalLimit+=70;drawGlobalResults();break;case 'toggle-bookmark':toggleBookmark().catch(showError);break;case 'save-note':saveNote().catch(showError);break;case 'copy-rule':copyRecord().catch(showError);break;case 'download-rule':downloadRecord();break;case 'print-rule':window.print();break;case 'start-compare':runCompare().catch(showError);break;case 'close-modal':closeModal();break;}}
function bindEvents(){document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;
if(target.dataset.view){nav(target.dataset.view);return;}if(target.dataset.action){handleAction(target.dataset.action);return;}
if(target.dataset.openFamily){openFamily(target.dataset.openFamily).catch(showError);return;}
if(target.dataset.openRelease){openFamily(target.dataset.familyId,target.dataset.openRelease).catch(showError);return;}
if(target.dataset.activateRelease){(async()=>{await setActive(target.dataset.familyId,target.dataset.activateRelease);showToast('Aktif mevzuat sürümü değiştirildi.');await renderScreen();})().catch(showError);return;}
if(target.dataset.removeRelease){removeRelease(target.dataset.removeRelease).catch(showError);return;}if(target.dataset.downloadRaw){downloadOriginalXml(target.dataset.downloadRaw).catch(showError);return;}
if(target.dataset.openRule){state.selectedKey=target.dataset.openRule;refreshReaderSelection();const reader=document.getElementById('readerDetail');if(reader&&target.classList.contains('related-link'))reader.scrollIntoView({block:'start',behavior:'smooth'});return;}
if(target.dataset.readerKind){state.readerKind=target.dataset.readerKind;state.readerLimit=90;paintReaderChips();refreshReaderList();return;}
if(target.dataset.globalOpen){openFamily(target.dataset.globalOpen,target.dataset.releaseId,target.dataset.recordKey).catch(showError);return;}
if(target.dataset.openAnnotation){openFamily(target.dataset.openAnnotation,null,target.dataset.recordKey).catch(showError);return;}
if(target.dataset.compareFamily){state.diffFamily=target.dataset.compareFamily;state.diffOld=null;state.diffNew=null;state.diffRows=[];state.diffFilter='CHANGES';nav('compare');return;}
if(target.dataset.diffFilter){state.diffFilter=target.dataset.diffFilter;document.querySelectorAll('[data-diff-filter]').forEach(x=>x.classList.toggle('active',x.dataset.diffFilter===state.diffFilter));drawDiffList();return;}
if(target.dataset.diffIndex!==undefined){state.diffSelected=Number(target.dataset.diffIndex);drawDiffList();return;}
});
document.addEventListener('input',e=>{if(e.target.id==='readerQuery'){state.readerQuery=e.target.value;state.readerLimit=90;clearTimeout(pendingSearch);pendingSearch=setTimeout(()=>refreshReaderList(),170);}if(e.target.id==='globalQuery'){state.globalQuery=e.target.value;state.globalLimit=70;clearTimeout(pendingSearch);pendingSearch=setTimeout(()=>runGlobalSearch().catch(showError),250);}});
document.addEventListener('change',e=>{if(e.target.id==='readerCategory'){state.readerCategory=e.target.value;state.readerLimit=90;refreshReaderList();}if(e.target.id==='readerVersion'){state.releaseId=e.target.value;state.selectedKey=null;state.readerQuery='';state.readerCategory='ALL';state.readerKind='ALL';renderReader().catch(showError);}if(e.target.id==='globalFamily'){state.globalFamily=e.target.value;state.globalLimit=70;runGlobalSearch().catch(showError);}if(e.target.id==='globalKind'){state.globalKind=e.target.value;state.globalLimit=70;runGlobalSearch().catch(showError);}if(e.target.id==='diffOld')state.diffOld=e.target.value;if(e.target.id==='diffNew')state.diffNew=e.target.value;});
document.getElementById('xmlFiles').addEventListener('change',e=>{const f=[...e.target.files];e.target.value='';importFiles(f).catch(err=>{modalLocked=false;closeModal();showError(err);});});document.getElementById('backupFile').addEventListener('change',e=>{const f=e.target.files?.[0];e.target.value='';restoreBackup(f).catch(showError);});document.getElementById('menuButton').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));document.getElementById('topQuery').addEventListener('keydown',e=>{if(e.key==='Enter'){state.globalQuery=e.target.value;nav('search');}});document.getElementById('modalLayer').addEventListener('click',e=>{if(e.target.id==='modalLayer')closeModal();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});document.addEventListener('submit',e=>{if(e.target.id==='firebaseForm'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));saveCloudConfig(data).catch(showError);}});}
(async function startup(){bindEvents();showLoading('Bulut kütüphanesi başlatılıyor…');try{if(window.EASA_CONFIG_READY)await window.EASA_CONFIG_READY;await startDB();const config=readCloudConfig();if(EasaCloud.configured(config)){try{await EasaCloud.init(config,handleCloudUserChange);cloudConnected=true;}catch(e){showError(e);}}await refreshMetadata();await renderScreen();if(!persistent)showToast('Tarayıcı önbelleği geçici. Bulut verileri korunur ancak çevrimdışı okuma çalışmayabilir.','warn');}catch(err){showError(err);nav('settings');}})();
